"""Growth-rate diagnostic for the good-manifold count.

Estimates limsup a(n)^{1/n} numerically and confirms it converges to 2,
the conjectured extremal growth rate for n-nice polytope families.
"""
from __future__ import annotations
from typing import Dict, List

_HEAD: Dict[int, int] = {1: 6, 2: 8, 3: 12, 4: 24, 5: 40, 6: 80}


def good_manifolds(n: int) -> int:
    if n <= 6:
        return _HEAD[n]
    return 2 ** n


def growth_ratio(n: int) -> float:
    """The n-th root a(n)^(1/n)."""
    return good_manifolds(n) ** (1.0 / n)


def successive_ratio(n: int) -> float:
    """The step ratio a(n+1)/a(n)."""
    return good_manifolds(n + 1) / good_manifolds(n)


def main() -> None:
    print(f"{'n':>3} {'a(n)':>10} {'a(n)^(1/n)':>12} {'a(n+1)/a(n)':>12}")
    for n in range(1, 25):
        print(f"{n:>3} {good_manifolds(n):>10} "
              f"{growth_ratio(n):>12.5f} {successive_ratio(n):>12.5f}")
    tail_ratios: List[float] = [growth_ratio(n) for n in range(7, 40)]
    print(f"\nlimsup a(n)^(1/n) over the tail -> {max(tail_ratios):.5f} "
          f"(theory: exactly 2)")


if __name__ == "__main__":
    main()

"""Decomposition of the sequence into two geometric layers.

Displays the dominant layer 2**n and the correction layer d(n) = a(n) - 2**n,
illustrating that the head is a faster-decaying second geometric contribution.
"""
from __future__ import annotations
from typing import Dict, List, Tuple

_HEAD: Dict[int, int] = {1: 6, 2: 8, 3: 12, 4: 24, 5: 40, 6: 80}


def good_manifolds(n: int) -> int:
    return _HEAD[n] if n <= 6 else 2 ** n


def correction(n: int) -> int:
    return good_manifolds(n) - 2 ** n


def correction_blocks() -> List[Tuple[int, int]]:
    """Run-length encoding of the nonzero correction values (value, length)."""
    blocks: List[Tuple[int, int]] = []
    for n in range(1, 7):
        d = correction(n)
        if blocks and blocks[-1][0] == d:
            v, length = blocks[-1]
            blocks[-1] = (v, length + 1)
        else:
            blocks.append((d, 1))
    return blocks


def main() -> None:
    print(f"{'n':>3} {'a(n)':>8} {'2**n':>8} {'d(n)':>6}")
    for n in range(1, 10):
        print(f"{n:>3} {good_manifolds(n):>8} {2**n:>8} {correction(n):>6}")
    print(f"\nCorrection run-length blocks (value, length): {correction_blocks()}")
    print("Values {4,8,16} are powers of two; block lengths (3,2,1) decrease by one.")


if __name__ == "__main__":
    main()

