from __future__ import annotations
from typing import Dict

_HEAD: Dict[int, int] = {1: 6, 2: 8, 3: 12, 4: 24, 5: 40, 6: 80}


def good_manifolds(n: int) -> int:
    """Maximal number of good manifolds in an n-nice polytope, n >= 1.

    O(log n) via fast exponentiation for the tail; O(1) table lookup for
    the head (dimensions 1..6).
    """
    if n < 1:
        raise ValueError("dimension must be a positive integer")
    if n <= 6:
        return _HEAD[n]
    return 1 << n  # 2**n via bit shift

from __future__ import annotations
from typing import Dict

_HEAD: Dict[int, int] = {1: 6, 2: 8, 3: 12, 4: 24, 5: 40, 6: 80}


def good_manifolds(n: int) -> int:
    return _HEAD[n] if n <= 6 else 2 ** n


def tail_partial_sum(m: int) -> int:
    """Closed-form sum a(7)+...+a(m) for m >= 7, computed in O(log m).

    Uses the geometric identity sum_{k=7}^m 2**k = 2**(m+1) - 2**7,
    avoiding term-by-term addition.
    """
    if m < 7:
        raise ValueError("closed-form sum valid only for m >= 7")
    return (1 << (m + 1)) - (1 << 7)

